5612						? sha256(bytes)
5613						: value.integrity?.canonicalDigest;
5614				if (bound !== app.canonicalDigest)
5615					throw new Error(`${app.app} canonical receipt silently rebound`);
5616				return {
5617					app: app.app,
5618					path: app.canonicalReceipt,
5619					sha256: sha256(bytes),
5620					canonicalDigest: app.canonicalDigest,
5621				};
5622			}),
